/// <summary>
/// designed from AVA
/// </summary>
public void clicked()
{
    next clicked();

    FormRun                 formRun = this.formRun();
    FormDataSource          prodParmStartupDS = formRun.dataSource(formDataSourceStr(ProdParmStartup,prodParmStartup));
    ProdParmStartup         prodParmStartup = prodParmStartupDS.cursor();

    SRSPrintDestinationSettings printJobSettings;

    printJobSettings = new SRSPrintDestinationSettings(prodParmStartup.AVASetupPrintProdRunMap);
    SrsReportRunUtil::showSettingsDialog(printJobSettings);
    prodParmStartup.AVASetupPrintProdRunMap = printJobSettings.pack();
}
